fetch { "Director": $p.person_name, "TotalRevenue": $total_revenue };

match
$pc isa production_company, has production_company_name $name;
$a isa adult_video;
produced_by (media: $a, producer: $pc);
reduce $count = count($a) groupby $pc, $name;
sort $count desc;
limit 3;
fetch { "name": $name, "num_adult_films": $count };

match
$pc isa production_company, has production_company_name $name;
$a isa adult_video;
produced_by (media: $a, producer: $pc);
reduce $count = count($a) groupby $pc, $name;
sort $count desc;
limit 3;
fetch {
  "ProductionCompany": $name,
  "NumberOfAdultFilms": $count
};

match
$pc isa production_company, has production_company_name $name;
$m isa movie;
produced_by (media: $m, producer: $pc);
spoken_in_language (media: $m, language: $l);
select $pc, $name, $l;
distinct;
reduce $lang_count = count($l) groupby $pc, $name;
match $lang_count > 3;
sort $lang_count desc;
limit 3;
fetch { "ProductionCompany": $name, "languageCount": $lang_count };

match
$m isa machine, has name $mn;
$t isa machine_type_spec, has disk $d;
$d > 256;
typed_as (machine: $m, spec: $t);
routes (routing_device: $m, routed_interface: $i);
$nz isa network_zone, has zone $z;
$z == 4;
routes (routing_device: $nz, routed_interface: $i);
fetch {
  "name": $mn
};

match
  $s isa software, has name "webapp";
  $a isa application;
  instance_of (running_instance: $a, template: $s);
limit 3;
fetch {
  "name": $a.name
};

match
$s isa software, has name $sn;
$a isa application, has name $an;
instance_of (template: $s, running_instance: $a);
select $sn, $an;
distinct;
fetch {
  "SoftwareName": $sn,
  "ApplicationName": $an
};

match
$e isa offshore_entity, has status "Active", has name $n;
officer_of (officer: $o, offshore_entity: $e);
reduce $officer_count = count($o) groupby $e, $n;
match $officer_count > 1;
fetch { "entityName": $n, "officerCount": $officer_count };

match
$m isa movie, has movie_id $mid, has title $t;
rated (user: $u, film: $m);
$mid like "1.*";
select $t, $mid;
distinct;
fetch {
  "title": $t,
  "movieId": $mid
};

match
$q isa question;
tagged (question: $q, tag: $t);
answered (question: $q, answer: $a);
reduce $tag_count = count($t), $answer_count = count($a) groupby $q;
sort $tag_count desc, $answer_count desc;
limit 3;
fetch {
  "question_title": $q.title,
  "question_link": $q.question_link,
  "tag_count": $tag_count,
  "answer_count": $answer_count
};

match
$q isa question, has answer_count $ac, has view_count $vc;
$ac > 0;
answered (question: $q, answer: $a);
reduce $count = count($a) groupby $q, $vc;
sort $count desc, $vc desc;
limit 3;
match
answered (question: $q, answer: $acceptedAnswer);
$acceptedAnswer has is_accepted true;
fetch {
  "questionTitle": $q.title,
  "questionLink": $q.question_link,
  "acceptedAnswerLink": $acceptedAnswer.answer_link,
  "acceptedAnswerBody": $acceptedAnswer.body_markdown
};

match
$u isa user;
$s isa stream;
chat_activity (chatting_user: $u, chatting_channel: $s);
vip_status (vip_user: $u, vip_channel: $s);
limit 5;
fetch { "userName": $u.name };

match
$s isa stream;
$u isa user;
vip_status (vip_user: $u, vip_channel: $s);
moderation (moderating_user: $u, moderated_channel: $s);
fetch {
  "streamName": $s.name,
  "streamUrl": $s.url,
  "userName": $u.name
};

match
$u isa user;
$s isa stream, has total_view_count $tvc;
$tvc > 5000000;
vip_status (vip_user: $u, vip_channel: $s);
fetch {
  "name": $u.name
};

match
$u isa user;
$s1 isa stream;
$s2 isa stream;
moderation (moderating_user: $u, moderating_channel: $s1);
vip_status (vip_user: $u, vip_channel: $s2);
not { $s1 is $s2; };
limit 3;
fetch {
  "userName": $u.name
};

match
$u isa user;
$s isa stream, has followers $f, has created_at $ca;
$f < 10000;
vip_status (vip_user: $u, vip_channel: $s);
sort $ca;
limit 5;
fetch { "name": $u.name };

match
$u isa user, has name $name;
$s isa stream;
vip_status (vip_user: $u, vip_channel: $s);
reduce $count = count($s) groupby $u, $name;
sort $count desc;
limit 5;
fetch {
  "userName": $name,
  "streamCount": $count
};

match
  $u isa user, has name "itsbigchase";
  $s isa stream;
  moderation (moderating_user: $u, moderated_channel: $s);
  vip_status (vip_user: $u, vip_channel: $s);
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url
};

match
$u isa user, has name $uname;
$s1 isa stream, has name "itsbigchase";
$s2 isa stream;
not { $s2 is $s1; };
vip_status (vip_user: $u, channel_with_vips: $s1);
vip_status (vip_user: $u, channel_with_vips: $s2);
fetch {
  "vipUser": $uname
};

match
$s isa stream;
$u isa user;
moderation (moderating_user: $u, moderated_channel: $s);
vip_status (vip_user: $u, vip_channel: $s);
fetch {
  "stream_name": $s.name,
  "moderator_vip_name": $u.name
};

match
$u isa user, has name $un;
$s isa stream, has name $sn, has total_view_count $tvc;
$tvc > 1000000;
vip_status (vip_user: $u, channel_with_vips: $s);
limit 3;
fetch {
  "VIP_User": $un,
  "Stream_Name": $sn,
  "Total_View_Count": $tvc
};

match
$u isa user;
$s isa stream;
vip_status (vip_user: $u, channel_with_vips: $s);
reduce $count = count($s) groupby $u;
match $count > 3;
fetch { "name": $u.name };

match
  $s isa stream;
  $u isa user;
  vip_status (channel_with_vips: $s, vip_user: $u);
  moderation (moderated_channel: $s, moderating_user: $u);
limit 5;
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url,
  "user_name": $u.name
};

match
$u isa user;
$s isa stream;
vip_status (vip_user: $u, vip_channel: $s);
reduce $vip_count = count($s) groupby $u;
sort $vip_count desc;
limit 5;
fetch { "userName": $u.name, "vip_count": $vip_count };

match
$s isa stream;
$u isa user;
moderation (moderating_user: $u, moderated_channel: $s);
vip_status (vip_user: $u, vip_channel: $s);
fetch {
  "streamName": $s.name,
  "userName": $u.name
};

match
$u isa user;
$s isa stream, has total_view_count $tvc;
$tvc > 10000;
vip_status (vip_user: $u, vip_channel: $s);
limit 3;
fetch {
