match
$u isa user, has name $n;
$s isa stream;
vip_status (vip_user: $u, vip_channel: $s);
reduce $count = count($s) groupby $u, $n;
sort $count desc;
limit 3;
fetch { "userName": $n, "vip_stream_count": $count };

match
$vipUser isa user;
vip_status (vip_user: $vipUser, vip_channel: $stream);
reduce $streamCount = count($stream) groupby $vipUser;
sort $streamCount desc;
limit 3;
fetch { "vipUserName": $vipUser.name, "streamCount": $streamCount };

