  $s isa stream, has name $sn, has total_view_count $tvc;
  vip_status (vip_user: $u, channel_with_vips: $s);
  $tvc > 500000;
fetch {
  "vip_user": $un,
  "stream_name": $sn,
  "view_count": $tvc
};

match
$u isa user;
$s isa stream;
vip_status (vip_user: $u, vip_channel: $s);
reduce $streamCount = count($s) groupby $u;
match
$streamCount > 1;
fetch {
  "vipUser": $u.name,
  "streamCount": $streamCount
};

match
$u isa user, has name $n;
$s isa stream;
moderation (moderating_user: $u, moderated_channel: $s);
vip_status (vip_user: $u, vip_channel: $s);
limit 3;
fetch {
  "name": $n
};

match
$u isa user;
$s isa stream;
vip_status (vip_user: $u, vip_channel: $s);
reduce $streamCount = count($s) groupby $u;
sort $streamCount desc;
limit 3;
fetch { "userName": $u.name, "streamCount": $streamCount };

match
$u isa user;
$s isa stream;
vip_status (vip_user: $u, vip_channel: $s);
reduce $count = count($s) groupby $u;
sort $count desc;
limit 3;
fetch { "userName": $u.name, "vip_stream_count": $count };

match
